        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1];
            var r = last.results || {};

            var snapshot = {
                corminSat: r.corminSat || 0, comunidadSat: r.comunidadSat || 0,
                meridianSat: r.meridianSat || 0, alianzaSat: r.alianzaSat || 0,
                corminTrust: r.corminTrust || 0, comunidadTrust: r.comunidadTrust || 0,
                meridianTrust: r.meridianTrust || 0, alianzaTrust: r.alianzaTrust || 0,
                npv: r.npv || 0,
                corminSigned: !!r.corminSigned, comunidadSigned: !!r.comunidadSigned,
                meridianSigned: !!r.meridianSigned, alianzaSigned: !!r.alianzaSigned
            };
            // Same calculator the round loop writes to domainState — the reported score
            // and the graded score cannot diverge.
            var sc = this._score(snapshot);
            var totalScore = sc.total, signed = sc.signed, avgSat = sc.avgSat, trustAvg = sc.trustAvg;

            var perfKey = 'perf_novice';
            if (totalScore >= 70 && signed === 4) perfKey = 'perf_master';
            else if (totalScore >= 55) perfKey = 'perf_skilled';
            else if (totalScore >= 40) perfKey = 'perf_developing';

            var insights = [];
            if (signed === 4) {
                insights.push(this._t('insight_all_signed', 'All four stakeholders signed the Project Development Agreement — a remarkable achievement in multi-party negotiation.'));
            } else {
                var holdouts = [];
                if (!snapshot.corminSigned)    holdouts.push(this._t('cormin_name', 'CORMIN'));
                if (!snapshot.comunidadSigned) holdouts.push(this._t('comunidad_name', 'Comunidad'));
                if (!snapshot.meridianSigned)  holdouts.push(this._t('meridian_name', 'Meridian'));
                if (!snapshot.alianzaSigned)   holdouts.push(this._t('alianza_name', 'Alianza'));
                insights.push(this._t('insight_holdouts', 'The following parties withheld their signature:') + ' ' + holdouts.join(', ') + '.');
            }
            if (avgSat >= 60)      insights.push(this._t('insight_value_high', 'Strong interest-based negotiation — you found substantial value beyond positional bargaining.'));
            else if (avgSat >= 40) insights.push(this._t('insight_value_mid', 'Moderate value creation — some interest-based trades discovered but room for improvement.'));
            else                   insights.push(this._t('insight_value_low', 'Limited value creation — the proposal remained largely positional.'));

            if (snapshot.npv >= 1400)      insights.push(this._t('insight_npv_high', 'Excellent NPV preservation — you balanced concessions with project value effectively.'));
            else if (snapshot.npv < 1200)  insights.push(this._t('insight_npv_low', 'NPV significantly eroded — consider whether all concessions were strategically necessary.'));

            return {
                totalScore: totalScore,
                overallScore: totalScore,
                signed: signed,
                finalNPV: snapshot.npv,
                avgSatisfaction: Math.round(avgSat),
                avgTrust: Math.round(trustAvg),
                performance: this._t(perfKey, 'Negotiator'),
                insights: insights
            };
        }

